use genex::prelude::*;

#[derive(Default)]
pub struct World { rock: Model, rocks: Vec<Vec3> }

pub fn wire(game: &mut Game<World>) {
    game.on_reset(|sim, _seed, rng, gfx| {
        sim.world.rock = gfx.assets().model("rock.glb"); // once, never per instance
        sim.world.rocks = (0..40).map(|_| vec3(rng.range_f32(-10.0, 10.0), 0.0, rng.range_f32(-10.0, 10.0))).collect();
    });
    game.on_draw(|sim, frame, _camera| {
        frame.tag("rocks"); // every draw below counts under "rocks"
        for &at in &sim.world.rocks {
            frame.model(&sim.world.rock, Transform::from_translation(at));
        }
    });
}
